#ifndef RH_DATA_H
#define RH_DATA_H
// Romhack: randomizer data tables stored as files in the code-addon NARC (a028), read on demand.
// Generated by tools/rh/gen_rh_data.py.

#define CODE_ADDON_RH_SPECIES_INFO 20

#define RH_SPF_LEGENDARY     0x01
#define RH_SPF_VARIANT       0x02   // regional / alternate / cosmetic form
#define RH_SPF_MEGA          0x04   // Mega Evolution
#define RH_SPF_POOL          0x08   // can be picked at all
#define RH_SPF_STRONG_LEGEND 0x10
#define RH_SPF_BASE          0x20   // base form of its species

#define RH_SPF2_REGIONAL     0x01   // regional form: a Pokemon of its own
#define RH_SPF2_MEGA_LIKE    0x02   // Mega / Primal / Ultra Burst
#define RH_SPF2_VIVILLON     0x04   // a Vivillon wing pattern (never picked itself)

// one per personal-data index
struct RhSpeciesInfo
{
    u16 key;      // base species | form << 11
    u16 bst;      // vanilla base stat total
    u16 preEvo;   // personal index of the direct pre-evolution (0 = basic)
    u8 type1, type2;
    u8 gsc;       // gen (bits 0-3) | stage-1 (bits 4-5) | chain-1 (bits 6-7)
    u8 flags;     // RH_SPF_*
    u8 children;  // distinct vanilla evolutions (forms once): all (bits 0-3), gen 1 (4-5), gens 1-3 (6-7)
    u8 flags2;    // RH_SPF2_*
};

// Wild encounter pairs (a028 member 21, tools/rh/gen_rh_wild.py). Zone mode m: 0 whole game, 1 whole game split
// by encounter type, 2 location, 3 location split, 4 map, 5 map split, 6 encounter set.
#define CODE_ADDON_RH_WILD 21

// a028 member 22: FVX estimated evolution levels, u8 [RH_EVO_BST_N][RH_EVO_BST_N] by (pre BST, post BST)
#define CODE_ADDON_RH_EVO_LEVELS 22
#define RH_EVO_BST_LO 100
#define RH_EVO_BST_STEP 10
#define RH_EVO_BST_N 71

// a028 member 23: the randomizers' move pool (tools/rh/gen_rh_moves.py): u16 count, u16 pad, then the moves by id
#define CODE_ADDON_RH_MOVES 23
#define RH_MOVE_MAX 800
#define RHM_BROKEN      0x01     // FVX "No Game-Breaking Moves"
#define RHM_GEN1_BROKEN 0x02     // ... with Gen 1 battle mechanics
#define RHM_NO_DAMAGING 0x04     // never a forced / "good" attack (FVX bannedForDamagingMove)
#define RHM_HM          0x08
#define RHM_HITS(f)     ((f) >> 4)
struct RhMove { u16 move; u8 flags; u8 pad; };
#define RH_WILD_BANKS 142
#define RH_WILD_PAIRS 1375
struct RhWildPair
{
    u16 species;     // personal index
    u8 bank;         // encounter bank (= map)
    u8 area;         // 0 land, 1 surfing, 2 Rock Smash, 3 fishing
    u8 low;          // lowest average level in this set
    u8 location;
    u16 rank[7];     // Catch Em' All rank of (zone, species) per mode
    u16 zoneRank[7]; // rank of the species inside its zone per mode (1-to-1 picks)
    u8 theme[7];     // type every Pokemon of the zone has (vanilla), 0xFF = none
    u8 zoneLow[7];   // lowest level of this species in the zone
    u8 relatives;    // bit m: a relative (same family) lives in the same zone in mode m
};
struct RhWildFile
{
    u16 bankStart[RH_WILD_BANKS + 1];
    struct RhWildPair pairs[RH_WILD_PAIRS];
};

#define RH_KEY_SPECIES(key) ((key) & 0x7FF)
#define RH_KEY_FORM(key)    ((key) >> 11)
#define RH_INFO_GEN(i)      ((i)->gsc & 15)
#define RH_INFO_STAGE(i)    ((((i)->gsc >> 4) & 3) + 1)
#define RH_INFO_CHAIN(i)    ((((i)->gsc >> 6) & 3) + 1)

#endif // RH_DATA_H
